import{_ as d,C as i,o as g,c as s,a2 as n,E as t}from"./chunks/framework.CCtxZRER.js";const y=JSON.parse('{"title":"Kenali Gudang Teknik","description":"Apa itu Gudang Teknik, apa saja fungsinya, dan dengan siapa saja gudang bekerja.","frontmatter":{"title":"Kenali Gudang Teknik","description":"Apa itu Gudang Teknik, apa saja fungsinya, dan dengan siapa saja gudang bekerja.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik","catatan-alur"],"kata_kunci":["gudang teknik","warehouse","fungsi gudang","penyimpanan","pengendalian","pelayanan","4 right","tanggung jawab","OS/PPIC","ERP","vendor"]},"headers":[],"relativePath":"divisi/index.md","filePath":"divisi/index.md"}'),u={name:"divisi/index.md"};function l(k,a,o,p,m,b){const e=i("DaftarKartu"),r=i("MermaidDiagram");return g(),s("div",null,[a[0]||(a[0]=n('<h1 id="kenali-gudang-teknik" tabindex="-1">Kenali Gudang Teknik <a class="header-anchor" href="#kenali-gudang-teknik" aria-label="Permalink to &quot;Kenali Gudang Teknik&quot;">​</a></h1><p class="lead">Gudang Teknik (warehouse) adalah tempat barang teknik diterima, disimpan, dirawat, dan disalurkan untuk mendukung kegiatan operasional perusahaan.</p><p>Moto gudang ini adalah <em><strong>A place for everything and everything in its place</strong></em>. Artinya, setiap barang punya tempatnya sendiri, dan setiap barang harus ada di tempatnya.</p><h2 id="barang-apa-saja-yang-ada-di-sini" tabindex="-1">Barang apa saja yang ada di sini? <a class="header-anchor" href="#barang-apa-saja-yang-ada-di-sini" aria-label="Permalink to &quot;Barang apa saja yang ada di sini?&quot;">​</a></h2><p>Barang pendukung produksi dan perbaikan mesin, misalnya spare part mesin, komponen mekanik, alat kerja teknisi, baut, mur, bearing, bahan perawatan, dan ATK. Daftar lengkapnya ada di <a href="./jenis-material">Jenis Material</a>.</p><h2 id="tiga-fungsi-utama" tabindex="-1">Tiga fungsi utama <a class="header-anchor" href="#tiga-fungsi-utama" aria-label="Permalink to &quot;Tiga fungsi utama&quot;">​</a></h2>',6)),t(e,{items:[{judul:"Penyimpanan",ket:"Menjaga barang tetap rapi, aman, mudah dicari, dan tidak rusak.",link:"/sop/penyimpanan-barang",ikon:"kotak"},{judul:"Pengendalian",ket:"Mencatat barang masuk, lokasi, jumlah stok, dan barang keluar.",link:"/divisi/administrasi-stok",ikon:"daftar"},{judul:"Pelayanan",ket:"Memastikan barang yang dibutuhkan divisi lain tersedia.",link:"/alur-kerja/barang-keluar",ikon:"keluar"}],kolom:1}),a[1]||(a[1]=n('<h2 id="prinsip-4-right" tabindex="-1">Prinsip 4 right <a class="header-anchor" href="#prinsip-4-right" aria-label="Permalink to &quot;Prinsip 4 right&quot;">​</a></h2><p>Setiap kali melayani permintaan, pastikan empat hal ini terpenuhi:</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th></th><th>Artinya</th></tr></thead><tbody><tr><td><strong>Right material</strong></td><td data-label="Artinya">Barangnya benar, sesuai kode dan spesifikasi.</td></tr><tr><td><strong>Right quantity</strong></td><td data-label="Artinya">Jumlahnya tepat, tidak kurang dan tidak lebih.</td></tr><tr><td><strong>Right condition</strong></td><td data-label="Artinya">Kondisinya baik dan siap dipakai.</td></tr><tr><td><strong>Right time</strong></td><td data-label="Artinya">Tersedia tepat waktu saat dibutuhkan.</td></tr></tbody></table><h2 id="dengan-siapa-gudang-bekerja" tabindex="-1">Dengan siapa gudang bekerja? <a class="header-anchor" href="#dengan-siapa-gudang-bekerja" aria-label="Permalink to &quot;Dengan siapa gudang bekerja?&quot;">​</a></h2>',4)),t(r,{code:"flowchart%20LR%0A%20%20accTitle%3A%20Pihak%20yang%20bekerja%20dengan%20Gudang%20Teknik%0A%20%20accDescr%3A%20Vendor%20mengantar%20barang%20ke%20Gudang%20Teknik.%20Gudang%20mengirim%20laporan%20barang%20masuk%20ke%20divisi%20OS%2FPPIC.%20Divisi%20lain%20memesan%20barang%20lewat%20ERP%20dan%20mengambilnya%20di%20gudang.%0A%20%20V(%5B%22Vendor%20%2F%20supplier%22%5D)%3A%3A%3Avendor%20--%20%22antar%20barang%22%20--%3E%20G%5B%22Gudang%20Teknik%22%5D%3A%3A%3Astaff%0A%20%20G%20--%20%22laporan%20barang%20masuk%22%20--%3E%20P%5B%22Divisi%20OS%2FPPIC%22%5D%3A%3A%3Adokumen%0A%20%20D(%5B%22Divisi%20lain%22%5D)%3A%3A%3Adivisi%20--%20%22pesan%20lewat%20ERP%22%20--%3E%20G%0A%20%20G%20--%20%22serahkan%20barang%22%20--%3E%20D%0A"}),a[2]||(a[2]=n('<ul><li><strong>Vendor / supplier</strong> mengantar barang yang dipesan.</li><li><strong>Divisi OS/PPIC</strong> menerima laporan bahwa barang sudah masuk dan sesuai.</li><li><strong>Divisi lain</strong> memesan barang lewat ERP, lalu karyawannya datang mengambil barang di gudang.</li></ul><p>Urutan lengkapnya ada di <a href="/WareHouse/alur-kerja/">Alur Warehouse</a>.</p><h2 id="ukuran-gudang-yang-baik" tabindex="-1">Ukuran gudang yang baik <a class="header-anchor" href="#ukuran-gudang-yang-baik" aria-label="Permalink to &quot;Ukuran gudang yang baik&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th></th><th>Artinya</th></tr></thead><tbody><tr><td><strong>Order fulfillment</strong></td><td data-label="Artinya">Permintaan dipenuhi dengan tepat.</td></tr><tr><td><strong>On-time</strong></td><td data-label="Artinya">Barang tersedia tepat waktu.</td></tr><tr><td><strong>Space utilization</strong></td><td data-label="Artinya">Ruang gudang dipakai dengan efisien.</td></tr><tr><td><strong>Stock accuracy</strong></td><td data-label="Artinya">Jumlah barang di rak sama dengan catatan.</td></tr></tbody></table><h2 id="yang-perlu-kamu-kuasai" tabindex="-1">Yang perlu kamu kuasai <a class="header-anchor" href="#yang-perlu-kamu-kuasai" aria-label="Permalink to &quot;Yang perlu kamu kuasai&quot;">​</a></h2><p>Setelah beberapa minggu magang, kamu diharapkan bisa:</p><ul><li>Mengenali kelompok barang dan contohnya.</li><li>Membaca kode barang dan mencocokkannya dengan barang aslinya.</li><li>Mengikuti alur barang masuk dan barang keluar.</li><li>Mengisi catatan manual di rak dengan benar.</li><li>Mengambil barang dengan prinsip FIFO.</li><li>Bekerja dengan aman dan memakai APD.</li></ul><p>Ada istilah yang belum kamu pahami? Buka <a href="./glosarium">Kamus Istilah</a>.</p>',8))])}const c=d(u,[["render",l]]);export{y as __pageData,c as default};
